// Files list: reads document _metadata .csv so every version of every RAG policy is loaded
// with its own version and dates. Nothing is hard coded except which doc_ids go in the RAG.
const base = 'https://raw.githubusercontent.com/Wenting-Hou/FinTech-Credit-Loan-Review/main/';
const RAG_DOCS = ['ELIG-001', 'RISK-TIER', 'PRODUCT-RISK', 'APPR-001', 'REG-001'];

function parseCsv(text) {
  text = String(text).replace(/^﻿/, '');
  const rows = []; let row = []; let cur = ''; let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i + 1] === '"') { cur += '"'; i++; } else inQuotes = false; }
      else cur += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(cur.trim()); cur = ''; }
    else if (c === '\n') { row.push(cur.trim()); rows.push(row); row = []; cur = ''; }
    else if (c !== '\r') cur += c;
  }
  if (cur !== '' || row.length) { row.push(cur.trim()); rows.push(row); }
  const [header, ...body] = rows.filter(r => r.some(v => v !== ''));
  return body.map(r => Object.fromEntries(header.map((h, i) => [h.trim(), r[i] ?? ''])));
}

const meta = parseCsv(await this.helpers.httpRequest({ url: base + 'metadata/document%20_metadata%20.csv', json: false }));

return meta
  .filter(m => RAG_DOCS.includes(m.doc_id))
  .map(m => ({ json: {
    file: m.file_name,
    doc_id: m.doc_id,
    version: m.version,
    effective_date: m.effective_date,
    effective_to: m.effective_to || '',
    url: base + 'data/documents/source/' + m.file_name,
  }}));

// Product rows: one chunk per product from loan_product.csv. The catalog holds the gates of the
// ELIG-001 version in force today, so each row gets that version and its dates from the metadata.
const base = 'https://raw.githubusercontent.com/Wenting-Hou/FinTech-Credit-Loan-Review/main/';

function parseCsv(text) {
  text = String(text).replace(/^﻿/, '');
  const rows = []; let row = []; let cur = ''; let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i + 1] === '"') { cur += '"'; i++; } else inQuotes = false; }
      else cur += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(cur.trim()); cur = ''; }
    else if (c === '\n') { row.push(cur.trim()); rows.push(row); row = []; cur = ''; }
    else if (c !== '\r') cur += c;
  }
  if (cur !== '' || row.length) { row.push(cur.trim()); rows.push(row); }
  const [header, ...body] = rows.filter(r => r.some(v => v !== ''));
  return body.map(r => Object.fromEntries(header.map((h, i) => [h.trim(), r[i] ?? ''])));
}
const yesNo = v => (String(v).toUpperCase() === 'TRUE' ? 'Yes' : 'No');

const products = parseCsv(await this.helpers.httpRequest({ url: base + 'data/structured/raw/loan_product.csv', json: false }));
const meta = parseCsv(await this.helpers.httpRequest({ url: base + 'metadata/document%20_metadata%20.csv', json: false }));

const today = new Date().toISOString().slice(0, 10);
const elig = meta.find(m => m.doc_id === 'ELIG-001' && m.effective_date <= today && (!m.effective_to || today <= m.effective_to));
if (!elig) throw new Error('No ELIG-001 version is in force today, so the catalog version is unknown.');
const to = elig.effective_to || 'open';

return products.map(r => ({ json: {
  text:
    `[loan_product.csv | catalog for ELIG-001 ${elig.version} | in force ${elig.effective_date} to ${to}] ` +
    `Catalog gate for ${r.product_code} (${r.product_name}, ${r.product_family}). ` +
    `Minimum applicant risk tier: ${r.minimum_risk_tier}. Minimum FICO: ${r.minimum_fico}. ` +
    `Accepts applicant with no credit score: ${yesNo(r.allow_no_score_flag)}. ` +
    `Maximum payment DTI: ${r.max_dti_pct}%. Maximum amount: $${r.maximum_amount_usd}. ` +
    `Bankruptcy allowed: ${yesNo(r.allow_bankruptcy_flag)}. Collections allowed: ${yesNo(r.allow_collections_flag)}. ` +
    `Base rate: ${r.base_rate_pct}%. Tier rate adjustments: ${r.tier_rate_adjustment_rule}.`,
  doc_id: 'loan_product.csv',
  source_file: 'loan_product.csv',
  product_code: r.product_code,
  version: elig.version,
  effective_date: elig.effective_date,
  effective_to: elig.effective_to || '',
}}));

// Guardrail: runs BEFORE retrieval. Code, not the LLM, decides:
//   1. which product the question is about (product code or plain product name)
//   2. which policy versions were in force on the application date (document _metadata .csv)
//   3. the numeric gates of the ELIG-001 version in force (its Catalog Gates table)
//   4. which applicant inputs are given, which are missing, and the gate results when all six are given
//   5. whether the question mentions a factor the policy prohibits
// route: 'answer' (retrieve, then LLM), 'no_policy' (retrieve for evidence, fixed reply), 'ask' (fixed reply, no retrieval)
const question = String($input.first().json.chatInput || '').trim();
const base = 'https://raw.githubusercontent.com/Wenting-Hou/FinTech-Credit-Loan-Review/main/';
const RAG_DOCS = ['ELIG-001', 'RISK-TIER', 'PRODUCT-RISK', 'APPR-001', 'REG-001'];   // keep in sync with "Files list"

function parseCsv(text) {
  text = String(text).replace(/^﻿/, '');
  const rows = []; let row = []; let cur = ''; let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i + 1] === '"') { cur += '"'; i++; } else inQuotes = false; }
      else cur += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(cur.trim()); cur = ''; }
    else if (c === '\n') { row.push(cur.trim()); rows.push(row); row = []; cur = ''; }
    else if (c !== '\r') cur += c;
  }
  if (cur !== '' || row.length) { row.push(cur.trim()); rows.push(row); }
  const [header, ...body] = rows.filter(r => r.some(v => v !== ''));
  return body.map(r => Object.fromEntries(header.map((h, i) => [h.trim(), r[i] ?? ''])));
}
const get = async path => this.helpers.httpRequest({ url: base + path, json: false });
const products = parseCsv(await get('data/structured/raw/loan_product.csv'));
const meta = parseCsv(await get('metadata/document%20_metadata%20.csv'));
const money = v => Number(String(v).replace(/[$,\s]/g, ''));
const fmt$ = n => '$' + Math.round(n).toLocaleString('en-US');

// ---------------------------------------------------------------- 1. product
// Plain names come from the data: product_name = product_family + product level (e.g. "Credit Card" + "Elite").
const FAMILY_WORDS = {
  'Mortgage': /\b(mortgage|home loan|house loan)s?\b/i,
  'Credit Card': /\b(credit card|card)s?\b/i,
  'Auto Loan': /\b(auto|car|vehicle)\b/i,
};
const DISTINCT = ['fha', 'jumbo', 'elite', 'subprime'];   // safe to match without the family word
for (const p of products) {
  p.level = p.product_name.slice(p.product_family.length).replace(/[0-9+]/g, '').trim();   // "Elite", "Top-Tier"
}
const q = question.toLowerCase();
const codeHits = products.filter(p => new RegExp('\\b' + p.product_code.replace('-', '\\-') + '\\b', 'i').test(question));
const nameHits = products.filter(p => {
  const lvl = p.level.toLowerCase();
  const lvlRe = new RegExp('\\b' + lvl.replace('-', '[- ]?') + '\\b', 'i');
  if (!lvlRe.test(q)) return false;
  return DISTINCT.includes(lvl) || FAMILY_WORDS[p.product_family].test(q);
});
const found = [...new Map([...codeHits, ...nameHits].map(p => [p.product_code, p])).values()];
const familiesMentioned = Object.keys(FAMILY_WORDS).filter(f => FAMILY_WORDS[f].test(q));
const outOfCatalog = (q.match(/\b(student|personal|business|boat|rv|motorcycle|payday|home equity|heloc)\s+(loan|line)s?\b/i) || [])[0];
const isEligibilityQuestion = /\b(qualif|eligib|approv|deny|denied|denial|declin|accept|can i get|could i get)/i.test(question);

// ---------------------------------------------------------------- 2. point in time
const MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december'];
function findDate(s) {
  let m = s.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = s.match(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/);
  if (m) return new Date(Date.UTC(+m[3], +m[1] - 1, +m[2]));
  m = s.match(/\b(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d{1,2}),?\s+(\d{4})\b/i);
  if (m) return new Date(Date.UTC(+m[3], MONTHS.indexOf(m[1].toLowerCase()), +m[2]));
  return null;
}
const stated = findDate(question);
let asOf = (stated || new Date()).toISOString().slice(0, 10);
// "under V2.0" with no date: judge as of the day that version takes effect
const vMatch = question.match(/\b(?:V|version\s*)(\d)(?:\.(\d))?\b/i);
const namedVersion = vMatch ? meta.find(x => x.doc_id === 'ELIG-001' && x.version === `V${vMatch[1]}.${vMatch[2] || 0}`) : null;
if (!stated && namedVersion) asOf = namedVersion.effective_date;
const inForceOn = (m, d) => m.effective_date && m.effective_date <= d && (!m.effective_to || d <= m.effective_to);
const ragMeta = meta.filter(m => RAG_DOCS.includes(m.doc_id));
const inForce = ragMeta.filter(m => inForceOn(m, asOf));
const eligVersions = ragMeta.filter(m => m.doc_id === 'ELIG-001').sort((a, b) => a.effective_date.localeCompare(b.effective_date));
const elig = inForce.find(m => m.doc_id === 'ELIG-001');
const policyLine = m => `${m.doc_id} ${m.version} (in force ${m.effective_date} to ${m.effective_to || 'open'})`;

// ---------------------------------------------------------------- 3. gates of the ELIG-001 version in force
let gates = {};
let gateSource = '';
let gateSourceIds = [];
if (elig) {
  const md = await get('data/documents/source/' + elig.file_name);
  const section = md.split('## Catalog Gates')[1] || '';
  for (const line of section.split('\n')) {
    const c = line.trim().replace(/^\||\|$/g, '').split('|').map(s => s.trim().replace(/`/g, ''));
    if (c.length === 8 && products.some(p => p.product_code === c[0])) {
      gates[c[0]] = { tier: c[1], fico: +c[2], noScore: c[3] === 'Yes', dti: parseFloat(c[4]), amount: money(c[5]),
                      bankruptcy: c[6] === 'Yes', collections: c[7] === 'Yes' };
    }
  }
  // When the version in force is the one loan_product.csv holds, the two must agree.
  const csvMatches = products.every(p => gates[p.product_code] &&
    gates[p.product_code].tier === p.minimum_risk_tier && gates[p.product_code].fico === +p.minimum_fico &&
    gates[p.product_code].dti === +p.max_dti_pct && gates[p.product_code].amount === money(p.maximum_amount_usd));
  const ref = (md.split('## Product Code Reference')[1] || '').split('\n## ')[0];
  for (const line of ref.split('\n')) {
    const c = line.trim().replace(/^\||\|$/g, '').split('|').map(s => s.trim().replace(/`/g, ''));
    const p = c.length === 3 && products.find(x => x.product_code === c[2]);
    if (p) p.product_name = `${c[0]} ${c[1].replace(/[()]/g, '')}`;   // e.g. "Credit Card Elite 760+" under V2.0
  }
  gateSource = csvMatches
    ? `ELIG-001 ${elig.version} Catalog Gates, same values as loan_product.csv`
    : `ELIG-001 ${elig.version} Catalog Gates`;
  gateSourceIds = csvMatches ? [`ELIG-001 ${elig.version}`, 'loan_product.csv'] : [`ELIG-001 ${elig.version}`];
}

// ---------------------------------------------------------------- 4. applicant inputs
const inputs = {};
let m;
if ((m = question.match(/\b(?:risk\s+)?tier\s*(?:of\s*)?T?([1-5])\b/i) || question.match(/\bT([1-5])\b/))) inputs.tier = 'T' + m[1];
if (/\b(no|without)\s+(credit\s+|fico\s+)?(score|fico|credit history)\b/i.test(question)) inputs.noScore = true;
else if ((m = question.match(/\b(?:fico|credit score|score)\D{0,12}(\d{3})\b/i) || question.match(/\b(\d{3})\s*(?:fico|credit score)\b/i))) inputs.fico = +m[1];
if ((m = question.match(/\b(?:payment\s+)?(?:dti|debt[- ]to[- ]income)(?:\s+ratio)?\D{0,10}(\d{1,3}(?:\.\d+)?)\s*%?/i) ||
         question.match(/\b(\d{1,3}(?:\.\d+)?)\s*%\s*(?:payment\s+)?(?:dti|debt[- ]to[- ]income)/i))) inputs.dti = +m[1];
const dollarRe = /\$\s?(\d[\d,]*(?:\.\d+)?)\s*(k|thousand)?\b|\b(\d[\d,]*(?:\.\d+)?)\s*(k|thousand)\b/gi;
let income = null;
for (const d of question.matchAll(dollarRe)) {
  const n = money(d[1] || d[3]) * ((d[2] || d[4]) ? 1000 : 1);
  const before = question.slice(Math.max(0, d.index - 30), d.index).toLowerCase();
  if (/(income|salary|earn|make|making)\W*(of|is|about|around)?\W*$/.test(before) || /^\s*(a|per)\s+year|^\s*(annual|yearly|income)/i.test(question.slice(d.index + d[0].length, d.index + d[0].length + 15))) income = n;
  else if (inputs.amount === undefined) inputs.amount = n;
}
function flag(word) {
  const re = new RegExp('\\b' + word, 'i');
  const hit = question.match(re);
  if (!hit) return undefined;
  const before = question.slice(Math.max(0, hit.index - 40), hit.index);
  const clause = before.split(/[.;]|\bbut\b/i).pop();
  return !/\b(no|not|without|never|none|zero)\b/i.test(clause);
}
const bk = flag('bankrupt'); if (bk !== undefined) inputs.bankruptcy = bk;
const col = flag('collection'); if (col !== undefined) inputs.collections = col;

const NEED = [
  ['tier', 'applicant risk tier (T1 to T5, assigned under RISK-TIER from credit history)'],
  ['fico', 'FICO score (or "no credit score")'],
  ['dti', 'payment DTI %'],
  ['amount', 'requested amount'],
  ['bankruptcy', 'bankruptcy in the past 7 years (yes or no)'],
  ['collections', 'collections in the past 12 months (yes or no)'],
];
const has = k => (k === 'fico' ? (inputs.fico !== undefined || inputs.noScore) : inputs[k] !== undefined);
const missing = NEED.filter(([k]) => !has(k)).map(([, label]) => label);

// gate results, computed only when one product is named and all six inputs are given
const tierNum = t => +String(t).replace(/\D/g, '');
const amountLabel = p => (p.product_family === 'Credit Card' ? 'Maximum credit limit' : 'Maximum loan amount');
let gateResults = null;
if (found.length === 1 && elig && missing.length === 0) {
  const g = gates[found[0].product_code];
  const res = [];
  const tierOk = tierNum(inputs.tier) <= tierNum(g.tier);
  res.push(['Minimum risk tier', `applicant ${inputs.tier}, minimum ${g.tier}; ${inputs.tier} is ${tierOk ? 'the same as or better than' : 'a riskier tier than'} ${g.tier} (T1 is the best tier, T5 the riskiest)`, tierOk]);
  if (inputs.noScore) res.push(['Minimum FICO', `applicant has no credit score; product ${g.noScore ? 'accepts' : 'does not accept'} no score`, g.noScore]);
  else res.push(['Minimum FICO', `applicant ${inputs.fico}, minimum ${g.fico}`, inputs.fico >= g.fico]);
  res.push(['Maximum payment DTI', `applicant ${inputs.dti}%, maximum ${g.dti}%`, inputs.dti <= g.dti]);
  res.push([amountLabel(found[0]), `requested ${fmt$(inputs.amount)}, maximum ${fmt$(g.amount)}`, inputs.amount <= g.amount]);
  res.push(['Bankruptcy', `applicant ${inputs.bankruptcy ? 'has a' : 'has no'} bankruptcy in the past 7 years; product ${g.bankruptcy ? 'allows' : 'does not allow'} it`, !inputs.bankruptcy || g.bankruptcy]);
  res.push(['Collections', `applicant ${inputs.collections ? 'has' : 'has no'} collections in the past 12 months; product ${g.collections ? 'allows' : 'does not allow'} them`, !inputs.collections || g.collections]);
  const failed = res.filter(r => !r[2]).map(r => r[0]);
  gateResults = { lines: res.map(r => `${r[0]}: ${r[1]} -> ${r[2] ? 'PASS' : 'FAIL'}`), failed,
                  verdict: (failed.length ? `Not eligible for ${found[0].product_code}: fails ${failed.join(', ')}.` : `Meets all six catalog gates for ${found[0].product_code}.`) +
                    (inputs.noScore && g.noScore ? ' An applicant with no credit score goes to manual underwriting (ELIG-001 section 4).' : '') };
}

// ---------------------------------------------------------------- 5. prohibited factors and notes
const prohibited = [];
if (/\bdefault(s|ed)?\b/i.test(question)) prohibited.push('default outcome');
if (/\b(gender|sex|male|female)\b/i.test(question)) prohibited.push('gender');
if (/\b(marital|married|divorced|single parent|family status|children|kids)\b/i.test(question)) prohibited.push('family status');
const notes = [];
if (prohibited.length) notes.push(`The question mentions ${prohibited.join(', ')}, which RISK-TIER (applicant_risk_policy.md) prohibits as a factor, so it cannot be used.`);
if (/\bdebt burden\b/i.test(question)) notes.push('The debt burden ratio is a RISK-TIER input, not the payment DTI gate, so it is not used as DTI.');
if (income !== null) notes.push(`Income (${fmt$(income)}) is not one of the six catalog gates; it matters through payment DTI and the ability-to-repay check.`);
if (/\bapprov/i.test(question)) notes.push('This system retrieves policy evidence; it does not make approval decisions. Final decisions go to underwriting.');

// ---------------------------------------------------------------- route
const productList = products.map(p => `${p.product_name} (${p.product_code})`).join(', ');
let route = 'answer';
let reply = '';
if (outOfCatalog && found.length === 0) {
  route = 'ask';
  reply = `There is no "${outOfCatalog}" product in the catalog, so no policy covers it. The catalog has: ${productList}.`;
} else if (isEligibilityQuestion && found.length === 0) {
  route = 'ask';
  const fam = familiesMentioned.length === 1
    ? products.filter(p => p.product_family === familiesMentioned[0]).map(p => `${p.product_name} (${p.product_code})`).join(', ')
    : productList;
  reply = `Which product should I check? Options: ${fam}.` +
    (missing.length ? ` I will also need: ${missing.join('; ')}.` : '');
} else if (found.length > 1 && isEligibilityQuestion) {
  route = 'ask';
  reply = `The question names more than one product (${found.map(p => p.product_code).join(', ')}). Please ask about one product at a time.`;
} else if (!elig && (isEligibilityQuestion || found.length)) {
  route = 'no_policy';
  const first = eligVersions[0];
  reply = `No eligibility policy was in force on ${asOf}. According to document _metadata .csv, the earliest version of the eligibility rules (ELIG-001 ${first ? first.version : ''}) takes effect on ${first ? first.effective_date : 'an unknown date'}, ` +
    `so it cannot be applied to this application. Eligibility cannot be determined from the current corpus, and the case should be routed to manual review.`;
} else if (isEligibilityQuestion && missing.length) {
  route = 'ask';
  reply = `To check ${found[0].product_name} (${found[0].product_code}) under ELIG-001 ${elig.version}, I still need: ${missing.join('; ')}. ` +
    `Ask again with those values. The risk tier is never estimated from the FICO score.`;
}
if (route !== 'answer') {
  if (notes.length) reply += ' ' + notes.join(' ');
  reply += `\n\nSources: ${route === 'no_policy' ? 'document _metadata .csv' : 'loan_product.csv' + (elig && route === 'ask' && found.length ? `, ELIG-001 ${elig.version}` : '')}`;
}

// ---------------------------------------------------------------- facts for the LLM
const lines = [
  `Question: ${question}`,
  `Product named in the question: ${found.length ? found.map(p => `${p.product_code} (${p.product_name})`).join(', ') : 'none'}`,
  `Application date: ${asOf}${stated ? ' (stated in the question)' : namedVersion ? ` (not stated; the question names ELIG-001 ${namedVersion.version}, so its effective date is used)` : ' (not stated in the question; policies in force today are used)'}`,
  `Policies in force on that date (from document _metadata .csv): ${inForce.map(policyLine).join('; ') || 'none'}`,
];
for (const p of found) {
  const g = gates[p.product_code];
  if (g) lines.push(`Catalog gate in force for ${p.product_code} (source: ${gateSource}): minimum risk tier ${g.tier}; minimum FICO ${g.fico}; accepts no credit score ${g.noScore ? 'Yes' : 'No'}; maximum payment DTI ${g.dti}%; ${amountLabel(p).toLowerCase()} ${fmt$(g.amount)}; bankruptcy in the past 7 years allowed ${g.bankruptcy ? 'Yes' : 'No'}; collections in the past 12 months allowed ${g.collections ? 'Yes' : 'No'}.`);
}
const given = NEED.filter(([k]) => has(k)).map(([k]) =>
  k === 'fico' ? (inputs.noScore ? 'FICO: no credit score' : `FICO ${inputs.fico}`)
  : k === 'amount' ? `requested amount ${fmt$(inputs.amount)}`
  : k === 'dti' ? `payment DTI ${inputs.dti}%`
  : k === 'tier' ? `risk tier ${inputs.tier}`
  : `${k} ${inputs[k] ? 'yes' : 'no'}`);
if (given.length && isEligibilityQuestion) lines.push(`Applicant inputs read from the question: ${given.join('; ')}`);
if (gateResults) {
  lines.push('Gate results (computed by code from the catalog gate in force; use them exactly, do not recompute):');
  lines.push(...gateResults.lines.map(l => '- ' + l));
  lines.push(`Gate verdict: ${gateResults.verdict}`);
}
if (prohibited.length) lines.push(`Prohibited factors mentioned in the question (must not be used): ${prohibited.join(', ')}`);
if (notes.length) lines.push(`Notes: ${notes.join(' ')}`);

return [{ json: {
  route,
  reply,
  facts: lines.join('\n'),
  search_query: [question, ...found.map(p => `${p.product_code} ${p.product_name}`)].join(' '),
  question,
  product_codes: found.map(p => p.product_code),
  application_date: asOf,
  date_stated: !!stated,
  policies_in_force: inForce.map(m => `${m.doc_id} ${m.version}`),
  inputs,
  missing,
  gate_results: gateResults,
  gate_source_ids: found.length ? gateSourceIds : [],
  prohibited_factors: prohibited,
}}];

// Build context: takes the chunks returned by "Retrieve chunks" (Simple Vector Store, Get Many),
// labels each one with its metadata, keeps only chunks in force on the application date,
// and builds the prompt. The full retrieved list is returned as "evidence" for the A3 write-up.
const SHOW_EVIDENCE = true;        // append the retrieved top-K list to the chat reply
const FILTER_BY_METADATA = true;   // false = A3 section 4D 'before' run: pass the top chunks by similarity only, ignoring version, dates and product
const CONTEXT_K = 6;          // chunks passed to the LLM after filtering

const g = $('Guardrail').first().json;
const asOf = g.application_date;
const named = g.product_codes || [];
const clean = s => String(s ?? '').replace(/[{}]/g, m => (m === '{' ? '(' : ')'));   // the LLM chain treats braces as template variables

const retrieved = $input.all().map((it, i) => {
  const doc = it.json.document || it.json || {};   // Get Many returns { document: { pageContent, metadata }, score }
  const md = doc.metadata || {};
  const from = md.effective_date || '';
  const to = md.effective_to || '';
  let keep = true, reason = 'in force';
  if (!from) { keep = false; reason = 'no effective date in metadata'; }
  else if (from > asOf) { keep = false; reason = `not yet in force on ${asOf}`; }
  else if (to && to < asOf) { keep = false; reason = `superseded before ${asOf}`; }
  else if (md.product_code && named.length && !named.includes(md.product_code)) { keep = false; reason = 'catalog row for another product'; }
  let filterOff = '';
  if (!FILTER_BY_METADATA && !keep) { filterOff = reason; keep = true; reason = 'in force'; }
  return {
    rank: i + 1,
    score: typeof it.json.score === 'number' ? +it.json.score.toFixed(3) : null,
    doc_id: md.doc_id || '?', version: md.version || '', source: md.source_file || md.doc_id || '',
    product_code: md.product_code || '', effective_date: from, effective_to: to,
    keep, reason, filterOff, text: String(doc.pageContent || ''),
  };
});
const kept = retrieved.filter(r => r.keep).slice(0, CONTEXT_K);
for (const r of retrieved) if (r.keep && !kept.includes(r)) { r.keep = false; r.reason = `in force, but over the ${CONTEXT_K}-chunk limit`; r.over = true; }
// The only sources the answer may cite: the chunks actually passed to the LLM, plus where the gates came from
const sourceId = r => (r.doc_id === 'loan_product.csv' ? 'loan_product.csv' : `${r.doc_id} ${r.version}`.trim());
const allowedSources = [...new Set([...(g.gate_source_ids || []), ...kept.map(sourceId)])];

const context = kept.map((r, i) =>
  `[Chunk ${i + 1} | ${r.doc_id} ${r.version} | in force ${r.effective_date} to ${r.effective_to || 'open'} | ${r.source}]\n${r.text}`
).join('\n\n');

const system = `You are an assistant for loan eligibility review. Answer using ONLY the facts and context in the user message, in clear professional prose for a credit analyst.

How to write:
- One or two short paragraphs. No bullet points, no lists, no headings, no PASS/FAIL labels.
- State the conclusion in the first sentence, then explain it.
- End with a separate final line that starts with "Sources:" and lists only the sources you relied on, chosen from this list: ${allowedSources.join(', ') || 'none'}. Never cite anything that is not on that list.

Rules:
1. Use only the facts and the context. If something is not there, say it is not in the corpus. Never name a document that is not in "Policies in force" or in a chunk label.
2. Every chunk is labelled with its document, version and the dates it is in force.${FILTER_BY_METADATA ? ' All chunks shown are in force on the application date.' : ''} Never use numbers from a version that is not in force on the application date.
3. Numeric gates come only from the "Catalog gate in force" line.
4. If "Gate results (computed by code)" are given, use them exactly as written and do not recompute any comparison. Name every failed gate with both numbers, then say in one sentence which gates pass.
5. If the application date was not stated, say the answer uses the policies in force today.
6. Escalation procedures may describe exceptions, but an exception never overrides a failed catalog gate and never means an applicant is approved.
7. Never assume a value the question does not give, and never estimate the risk tier from the FICO score. T1 is the best tier and T5 the worst.
8. If prohibited factors are listed, say clearly that they cannot be used, and do not use them.
9. Never answer "should I approve." This system retrieves policy evidence; underwriting makes the decision.`;

const user = `${g.facts}\n\nContext (${kept.length} chunks${FILTER_BY_METADATA ? ` in force on ${asOf}` : ', top by similarity, not filtered'}):\n${context || '(no chunks in force)'}\n\nAnswer the question: ${g.question}`;

const evidence = SHOW_EVIDENCE
  ? `\n\nRetrieved evidence (top ${retrieved.length} by similarity, judged as of ${asOf}${FILTER_BY_METADATA ? '' : '; METADATA FILTER OFF'}):\n` +
    retrieved.map(r => `${r.rank}. ${r.keep ? 'USED' : r.over ? 'NOT USED' : 'DROPPED'} ${r.doc_id} ${r.version}${r.product_code ? ' ' + r.product_code : ''}` +
      `${r.score !== null ? ', score ' + r.score : ''}${r.keep ? (r.filterOff ? ' (filter off; would be dropped: ' + r.filterOff + ')' : '') : ' (' + r.reason + ')'}: "${r.text.replace(/\s+/g, ' ').slice(0, 70)}..."`).join('\n')
  : '';

return [{ json: {
  use_llm: g.route === 'answer',
  reply: g.reply,
  system_prompt: clean(system),
  user_prompt: clean(user),
  evidence,
  application_date: asOf,
  retrieved: retrieved.map(({ text, ...r }) => r),
  context_chunks: kept.length,
  filter_by_metadata: FILTER_BY_METADATA,
  allowed_sources: allowedSources,
}}];
